int verify_asn1_signature(const ASN1_ITEM *it, X509_ALGOR *a, ASN1_BIT_STRING *signature, void *asn, EVP_PKEY *pkey) {
    EVP_MD_CTX *ctx = NULL;
    const EVP_MD *md = NULL;
    int ret = -1;

    if (!a || !signature || !pkey || !asn) {
        return -1;
    }

    if (OBJ_obj2nid(a->algorithm) == NID_undef) {
        return -1;
    }

    md = EVP_get_digestbynid(OBJ_obj2nid(a->algorithm));
    if (!md) {
        return -1;
    }

    ctx = EVP_MD_CTX_new();
    if (!ctx) {
        return -1;
    }

    if (EVP_VerifyInit_ex(ctx, md, NULL) <= 0) {
        goto end;
    }

    if (EVP_VerifyUpdate(ctx, asn, it->s_free) <= 0) {
        goto end;
    }

    if (EVP_VerifyFinal(ctx, signature->data, signature->length, pkey) <= 0) {
        ret = 0;
        goto end;
    }

    ret = 1;

end:
    EVP_MD_CTX_free(ctx);
    return ret;
}

int verify_asn1_signature(const ASN1_ITEM *it, X509_ALGOR *a, ASN1_BIT_STRING *signature, void *asn, EVP_PKEY *pkey) {
    EVP_MD_CTX *md_ctx = NULL;
    const EVP_MD *digest = NULL;
    int ret = -1;
    unsigned char *sig = NULL;
    int siglen = 0;

    if (!a || !signature || !asn || !pkey)
        return -1;

    if (a->parameter) {
        ASN1_OBJECT *obj = a->parameter;
        if (!OBJ_obj2txt(NULL, 0, obj, 0))
            return -1;
        if ((digest = EVP_get_digestbyname(OBJ_nid2ln(OBJ_obj2nid(obj)))) == NULL)
            return -1;
    } else {
        if ((digest = EVP_sha256()) == NULL)
            return -1;
    }

    if ((md_ctx = EVP_MD_CTX_new()) == NULL)
        goto err;

    if (!EVP_DigestVerifyInit(md_ctx, NULL, digest, NULL, pkey))
        goto err;

    if (!EVP_DigestVerifyUpdate(md_ctx, asn, ASN1_item_i2d(asn, NULL, it)))
        goto err;

    if ((sig = OPENSSL_malloc(signature->length)) == NULL)
        goto err;

    memcpy(sig, signature->data, signature->length);
    siglen = signature->length;

    ret = EVP_DigestVerifyFinal(md_ctx, sig, siglen);

err:
    if (md_ctx)
        EVP_MD_CTX_free(md_ctx);
    if (sig)
        OPENSSL_free(sig);
    return (ret == 1) ? 1 : 0;
}

int verify_asn1_signature(const ASN1_ITEM *it, X509_ALGOR *a, ASN1_BIT_STRING *signature, void *asn, EVP_PKEY *pkey) {
    EVP_MD_CTX *ctx = NULL;
    const EVP_MD *md = NULL;
    int ret = -1;

    if (!a || !signature || !pkey || !asn) {
        return -1;
    }

    if (!OBJ_obj2txt(NULL, 0, a->algorithm, 0)) {
        return -1;
    }

    md = EVP_get_digestbyname(OBJ_nid2ln(OBJ_obj2nid(a->algorithm)));
    if (!md) {
        return -1;
    }

    ctx = EVP_MD_CTX_create();
    if (!ctx) {
        return -1;
    }

    if (!EVP_VerifyInit_ex(ctx, md, NULL)) {
        goto end;
    }

    if (!EVP_VerifyUpdate(ctx, asn, it->it->utype_size)) {
        goto end;
    }

    if (signature->length < 0 || signature->length > EVP_MAX_MD_SIZE) {
        goto end;
    }

    if (!EVP_VerifyFinal(ctx, signature->data, signature->length, pkey)) {
        goto end;
    }

    ret = 1;

end:
    EVP_MD_CTX_destroy(ctx);
    return ret;
}

