int verify_asn1_signature(const ASN1_ITEM *it, X509_ALGOR *a, ASN1_BIT_STRING *signature, void *asn, EVP_PKEY *pkey) {
    EVP_MD_CTX *md_ctx = NULL;
    const EVP_MD *md = NULL;
    unsigned char *sig = NULL;
    int sig_len = 0;
    int ret = -1;

    if (!a || !signature || !pkey || !asn) {
        return -1;
    }

    md = EVP_get_digestbyname(OBJ_nid2ln(a->algorithm));
    if (!md) {
        return -1;
    }

    md_ctx = EVP_MD_CTX_new();
    if (!md_ctx) {
        goto err;
    }

    if (!EVP_DigestInit_ex(md_ctx, md, NULL)) {
        goto err;
    }

    if (!it->it->s2i_func(it, NULL, &asn, md_ctx)) {
        goto err;
    }

    sig_len = signature->length;
    sig = signature->data;

    if (!EVP_DigestVerifyInit(md_ctx, NULL, md, NULL, pkey)) {
        goto err;
    }

    if (!EVP_DigestVerifyFinal(md_ctx, sig, sig_len)) {
        ret = 0;
        goto err;
    }

    ret = 1;

err:
    if (md_ctx) {
        EVP_MD_CTX_free(md_ctx);
    }

    return ret;
}
